style.css:
@-moz-document domain("ozon.ru"), domain("www.ozon.ru") {
/* ============================================================
     Ozon ships a full design-token system on :root — light
     tokens (--ozTextPrimary, --ozBGSecondary, --ozGray*, --ozWhite*
     …) drive most surfaces and text. It even carries a complete
     parallel dark set (--ozdt*), but never activates it when
     logged out. We retheme by remapping the LIGHT tokens to dark
     values, then patch the surfaces Ozon hardcodes to literal
     white (#fff) outside the token system: the header, product
     tiles (.tile-root), the footer, the PDP gallery stage and
     thumbnails, and every floating/sticky bar + dropdown.

     Selectors target stable [data-widget="…"] attributes and the
     structural .tile-root / typography (tsBody*, tsHeadline*)
     class families — NEVER content-hashed classes (.gq4_20 …),
     which rot on every build.

     Brand accents kept recognisable but tuned for dark:
       Ozon blue   #005bff -> #2e78ff (links/CTA on near-black)
       sale red    #f91155 -> #ff3c75
       positive    #10c44c (green, kept)
       rating gold #ffb800 (kept)
     ============================================================ */

  :root {
    color-scheme: dark;

    /* ---- our dark palette ---- */
    --d-bg: #14181d;          /* base canvas */
    --d-surface: #1c2128;     /* elevated cards / panels */
    --d-surface-2: #1a1f26;   /* secondary surface */
    --d-header: #0d1117;      /* header / footer / sticky bars */
    --d-border: #2a313a;      /* subtle border */
    --d-border-2: #353d47;    /* stronger border */
    --d-text: #e6edf3;        /* primary text */
    --d-text-2: #c4cdd6;      /* body text */
    --d-text-3: #9aa6b2;      /* muted / secondary */
    --d-text-4: #7d8893;      /* quaternary / hints */
    --d-blue: #2e78ff;        /* refined Ozon blue */
    --d-blue-hover: #5b96ff;
    --d-red: #ff3c75;         /* refined sale red */
    --d-green: #19c560;       /* positive */
    --d-gold: #ffc93c;        /* rating */

    /* ---- remap Ozon light text tokens -> light-on-dark ---- */
    --ozTextPrimary: var(--d-text) !important;
    --ozBlack: var(--d-text) !important;
    --ozCtrlNeutral: var(--d-text) !important;
    --ozTextSecondary: var(--d-text-3) !important;
    --ozTextTertiary: var(--d-text-2) !important;
    --ozTextQuaternary: var(--d-text-4) !important;
    /* "text on an inverse/brand ground" — must stay pure white, not our
       off-white text colour: it labels white-on-blue buttons and chips,
       where every point of contrast counts. */
    --ozTextPrimaryNegative: #ffffff !important;

    /* ---- remap Ozon light background tokens -> dark ---- */
    --ozBGPrimary: var(--d-bg) !important;
    --ozBGSecondary: var(--d-surface) !important;
    --ozBGTertiary: var(--d-surface-2) !important;
    --ozBGQuaternary: #2b333d !important;
    --ozBGPrimaryInverse: var(--d-surface) !important;
    --ozBGSecondaryInverse: var(--d-surface) !important;
    --ozBGPrimaryHover: #232a32 !important;
    --ozWhite: var(--d-surface) !important;
    --ozWhite1: var(--d-surface) !important;
    --ozWhite2: var(--d-surface-2) !important;

    /* ---- "Floor" / layer surface system (Ozon's elevation tokens,
       separate from --oz*; drive grid, cards, badges, panels) ---- */
    --layerFloor0: var(--d-bg) !important;       /* page floor */
    --layerFloor1: var(--d-surface) !important;  /* cards */
    --layerFloor2: var(--d-surface) !important;  /* nested */
    --layerFloor3: var(--d-surface-2) !important;
    --layerActiveFloor0: #232a32 !important;
    --layerActiveFloor1: #2b333d !important;
    --layerActiveFloor2: #2b333d !important;
    --layerActiveFloor3: #2b333d !important;
    --layerSurface: rgba(255, 255, 255, 0.04) !important;
    --layerActiveSurface: rgba(255, 255, 255, 0.1) !important;
    --layerCeil0: var(--d-surface) !important;
    --layerCeil1: var(--d-surface) !important;
    --layerOverlayParanja: rgba(255, 255, 255, 0.05) !important;
    --layerOverlayDimming: rgba(3, 8, 13, 0.6) !important;

    /* ---- grey scale: light end -> dark surfaces, dark end -> light text ---- */
    --ozGray90: #232a32 !important;
    --ozGray80: #2b333d !important;
    --ozGray70: var(--d-text-4) !important;
    --ozGray60: var(--d-text-3) !important;
    --ozGray40: var(--d-text-2) !important;
    --ozGray30: var(--d-text) !important;
    --ozGray20: var(--d-text) !important;

    /* ---- separators / dimming ---- */
    --ozSeparator: rgba(160, 175, 195, 0.16) !important;
    --ozSeparatorDark: rgba(160, 175, 195, 0.22) !important;
    --ozShadowSpread: rgba(0, 0, 0, 0.55) !important;
    --ozParandja: rgba(255, 255, 255, 0.04) !important;
    --ozParandjaHover: rgba(255, 255, 255, 0.08) !important;
    --ozCtrlNeutralPale: rgba(255, 255, 255, 0.05) !important;
    --ozHoverNeutralPale: rgba(255, 255, 255, 0.09) !important;
    --ozHoverNeutral: #e4e9f0 !important;
    --ozWhiteOverlay: rgba(20, 24, 29, 0.82) !important;
    --ozWhiteOverlay2: rgba(20, 24, 29, 0.62) !important;
    --ozWhiteOverlay3: rgba(20, 24, 29, 0.42) !important;
    /* Highlight plate under the pointed-at row of EVERY Ozon select dropdown
       (language, currency, address, delivery …). Literal #e5efff — a pale blue that
       is invisible on the white site and a near-white slab on ours, and since the
       option label is lifted to light text by the token remap, the row you are
       actually pointing at is the one row you cannot read (~1.02:1). It exists only
       under the cursor inside an opened menu, so no load-time scan and no static
       screenshot can reach it. Single-role: measured live, `background-color` on the
       option row is its ONLY use anywhere in the site's sheets, so it is safe at
       :root. Inverted rather than neutralised, keeping the blue tint that marks the
       row as the highlighted one. */
    --ozBluePale: #16233a !important;
    /* Same shape, same design-system module: a pale-green #c2eecf plate whose only
       two uses are `background-color` on a button variant and its :hover, with
       --ozTextPrimary (lifted to light by us) as the label — so the button paints
       light-on-light at ~1.1:1. That variant renders on no logged-out surface
       reachable here, so unlike --ozBluePale it is fixed from the stylesheet rather
       than against a live element; the remap is background-only either way. */
    --ozGreenPale: #13291d !important;

    /* ---- accents: keep brand identity, tune for dark ---- */
    --ozCtrlPrimary: var(--d-blue) !important;
    --ozAccentPrimary: var(--d-blue) !important;
    --ozTextAction: var(--d-blue) !important;
    --ozHoverPrimary: var(--d-blue-hover) !important;
    --ozAccentPrimaryHover: var(--d-blue-hover) !important;
    --ozBlue: var(--d-blue) !important;
    --ozBlueHover: var(--d-blue-hover) !important;
    --ozCtrlSale: var(--d-red) !important;
    --ozTextSale: var(--d-red) !important;
    --ozAccentAlert: var(--d-red) !important;
    --ozRed: var(--d-red) !important;
    --ozCtrlPositive: var(--d-green) !important;
    --ozTextPositive: var(--d-green) !important;
    --ozAccentSecondary: var(--d-green) !important;
    --ozGreenUi: var(--d-green) !important;
    --ozRating: var(--d-gold) !important;
    --ozYellowBrand: var(--d-gold) !important;
    --ozTextWarning: var(--d-gold) !important;

    /* ============================================================
       MODERN SEMANTIC TOKEN LAYER (--text* / --graphic* / --bg*).
       Ozon migrated off the legacy --oz* names: nearly every colour
       on the site now resolves through this layer (the "hardcoded
       rgb(7,7,7)" text is simply --textPrimary: #070707). Remapping
       it here is what lets us DELETE the blanket typography rules
       that used to force one colour on whole widgets and flattened
       the site's semantics — the sale pink, the Ozon-card green, the
       Ozon-fresh teal, link vs heading, active vs idle.

       Rules of the remap:
         * neutral dark text/icon tokens -> our light text scale
         * saturated brand tokens are KEPT, only lifted where they
           fail contrast on near-black (blue #005bff -> #2e78ff …)
         * "…Dynamic" / "…Inverted" / "…OnDark" tokens are ALREADY
           light (they paint on dark/brand grounds) -> untouched
         * saturated brand FILLS (--bgAccentPrimary pink pill,
           --bgOzonPrimary blue CTA, lime/gold promo fills) -> untouched
       ============================================================ */

    /* -- neutral text: dark -> light -- */
    --textPrimary: var(--d-text) !important;
    --textPremium: var(--d-text) !important;
    --textActivePremium: var(--d-text) !important;
    --textDarkKey: var(--d-text) !important;
    --textSecondary: var(--d-text-3) !important;
    --textTertiary: var(--d-text-4) !important;
    --textOxford: var(--d-text-3) !important;

    /* -- neutral icon/glyph ("graphic"): dark -> light -- */
    --graphicPrimary: var(--d-text) !important;
    --graphicKey: var(--d-text) !important;
    --graphicDarkKey: var(--d-text) !important;
    --graphicPremium: var(--d-text) !important;
    --graphicActivePremium: var(--d-text) !important;
    --graphicSecondary: var(--d-text-3) !important;
    --graphicTertiary: var(--d-text-4) !important;
    /* --graphicQuaternary is NOT a glyph colour on this site despite the name:
       every one of its uses is a SURFACE or a hairline — the review media-viewer
       letterbox stage, the PDP video stage, 1px separator pseudos, and a couple of
       borders/inset shadows. Natively it is rgba(0,26,52,.2), a 20%-alpha tint that
       reads as "barely there" on white. Lifting it to the opaque --d-text-4 turned
       the media-viewer stage into a solid mid-grey slab around every review photo
       and video. Mirror the native alpha with a light tint instead, so it stays a
       veil in every role. */
    --graphicQuaternary: rgba(206, 219, 235, 0.2) !important;
    --graphicTabbarIconPrimary: var(--d-text) !important;
    --graphicTabbarIconSecondary: var(--d-text-4) !important;
    --graphicOxford: var(--d-text-3) !important;

    /* NOT remapped: the "…OnLight" pair (--textPrimaryOnLight,
       --graphicPrimaryOnLight, --textSecondaryOnLight, …). The suffix
       names the CONTEXT, not the role: these are the dark values a
       component uses when it paints itself on a light ground — and
       several use them as a BACKGROUND for a dark pill with
       --textLightKey white text (the home promo-counter chip does
       exactly this). Lifting them turned that chip into white-on-white. */

    /* -- brand accents: identity kept, lifted to clear contrast -- */
    --textAction: var(--d-blue) !important;
    --textOzon: var(--d-blue) !important;
    --textActiveAction: var(--d-blue-hover) !important;
    --textActiveOzon: var(--d-blue-hover) !important;
    --graphicActionPrimary: var(--d-blue) !important;
    --graphicActiveActionPrimary: var(--d-blue-hover) !important;
    --graphicActiveOzon: var(--d-blue-hover) !important;
    --graphicPremiumBlue: #4d8bff !important;
    --graphicActivePremiumBlue: #4d8bff !important;
    --textAccent: var(--d-red) !important;
    --textAccentOnLight: var(--d-red) !important;
    --textActiveAccent: #ff6d97 !important;
    --textExpress: var(--d-red) !important;
    --textActiveExpress: #ff6d97 !important;
    --textNegative: #ff6a45 !important;
    --textMarketing: #8a82f6 !important;
    --textActiveMarketing: #a49dff !important;
    --textGuarantee: #c46bff !important;
    --graphicGuarantee: #c46bff !important;

    /* -- neutral light surfaces: light -> dark -- */
    --bgPrimary: var(--d-bg) !important;
    --bgControl: var(--d-surface) !important;
    --bgPremiumPrimary: var(--d-surface) !important;
    --bgSecondary: rgba(255, 255, 255, 0.06) !important;
    --bgActivePrimary: #2b333d !important;
    --bgActivePremiumPrimary: #2b333d !important;
    --bgSelectInverted: var(--d-surface) !important;
    --bgActiveSelectInverted: #2b333d !important;
    --bgTabbarPrimary: var(--d-header) !important;
    --bgOverlap: rgba(20, 24, 29, 0.55) !important;

    /* -- pale tinted callout panels: keep the hue, invert the value -- */
    --bgOpaqueSecondary: #1f2630 !important;
    --bgOpaqueActionSecondary: #16233a !important;
    --bgOpaqueOzonSecondary: #16233a !important;
    --bgOpaqueAccentSecondary: #2e1622 !important;
    --bgOpaqueApparelSecondary: #2e1622 !important;
    --bgOpaquePositiveSecondary: #13291d !important;
    --bgOpaqueNegativeSecondary: #2e1a17 !important;
    --bgOpaqueWarningSecondary: #2b2415 !important;
    --bgOpaqueMarketingSecondary: #232042 !important;
    --bgOpaqueFreshSecondary: #12292a !important;
    --bgOpaqueEconomSecondary: #2b2318 !important;
    --bgAccentOnLight: #2e1622 !important;
    --bgApparelPiggy: #2e1622 !important;
    --bgPositiveOnLight: #13291d !important;
    --bgWarningOnLight: #2b2415 !important;
    --bgMarketingOnLight: #232042 !important;
    --bgMarketingSecondarySolid: #232042 !important;

    /* -- scroll-fade gradients that hardcode a white end stop -- */
    --grFadeHorizontalFloor1: linear-gradient(
      to right,
      rgba(28, 33, 40, 0) 0%,
      var(--d-surface) 40%
    ) !important;
    --grFavouritePromoFade: linear-gradient(
      to right,
      rgba(28, 33, 40, 0) 0%,
      var(--d-surface) 100%
    ) !important;
  }

  /* ============================================================
     BASE
     ============================================================ */
  html, body {
    background-color: var(--d-bg) !important;
    color: var(--d-text) !important;
  }

  /* soften every bright border to a subtle dark one */
  * {
    border-color: var(--d-border) !important;
  }

  /* ============================================================
     NOTE — there is deliberately NO global `ts*` typography colour
     rule here. Ozon's ts* classes carry font metrics only; the text
     colour comes from the --text and --graphic tokens remapped above.
     A blanket `[class*="tsBodyControl"] { color: … }` outranks those
     tokens (attribute selector beats the token's element rule) and
     flattened every semantic colour on the site at once: the sale
     pink −NN%, the white label on the pink "Распродажа" pill, the
     Ozon-card green price, the "Вход с Apple" white label, the
     "или" divider, and every action link. Colour text through the
     tokens; only patch what the tokens genuinely cannot reach.
     ============================================================ */

  /* ============================================================
     LITERAL-WHITE SURFACE NEUTRALISER
     Ozon hardcodes white on many wrappers outside the tokens
     (inline styles + the .search-bar-wrapper / wallpaper shells).
     Repaint white/near-white backgrounds to elevated dark.
     ============================================================ */
  [style*="background-color: rgb(255, 255, 255)"],
  [style*="background-color:#fff"],
  [style*="background-color: #fff"],
  [style*="background: rgb(255, 255, 255)"],
  [style*="background:#fff"],
  [style*="background-color: rgb(245, 247, 250)"],
  [style*="background-color:#f5f7fa"],
  [style*="background-color: #f5f7fa"],
  .search-bar-wrapper,
  [data-widget="searchBarDesktop"] > div {
    background-color: var(--d-surface) !important;
  }
  [data-widget="wallpaper"] {
    background-color: var(--d-bg) !important;
  }
  /* the catalog ("Каталог") menu wraps its blue CTA button in a
     white shell; flatten the wrapper to the header colour but leave
     the blue button itself (a genuine brand CTA) untouched */
  [data-widget="catalogMenu"],
  [data-widget="catalogMenu"] > div {
    background-color: var(--d-header) !important;
    color: var(--d-text) !important;
  }
  [data-widget="searchBarDesktop"] div {
    background-color: transparent !important;
  }
  /* seasonal / promo container shells */
  [data-widget="seasonWidget"] {
    background-color: var(--d-bg) !important;
  }

  /* ------------------------------------------------------------
     CATALOG MEGA-MENU (Каталог flyout) — the full category panel is
     rendered through a Vue portal (.vue-portal-target) mounted at body
     level, OUTSIDE the catalogMenu widget, as a literal-WHITE panel
     (hashed uw_* class, no role/aria). The widget-scoped header rules
     never reach it, so on dark the whole category flyout opens stark
     white. It only mounts on click, so the page-load element-bg audit
     never sees it. Darken the portal panel to the base canvas; the
     category links keep the brand blue via the link rule, and headings
     are lifted to readable light below. ------------------------- */
  .vue-portal-target,
  .vue-portal-target > div {
    background-color: var(--d-bg) !important;
  }
  /* The flyout is a separate Vue bundle: it does NOT use the --text*
     tokens, it hardcodes literal colours (#070707 headings, navy
     rgba(0,26,51,.6) links, rgba(0,26,52,.2) rail glyphs, #005bff
     actions). So it needs explicit rules — but ones that PRESERVE the
     hierarchy. The old theme leaned on a global `a { color: blue }`,
     which painted all ~200 links AND the section headings the same
     blue, erasing heading-vs-link entirely. Colour by role instead:
     section headings + rail labels primary, category links secondary,
     "Еще" toggles and the loaded rail category action-blue. */
  .vue-portal-target a {
    color: var(--d-text-2) !important;
  }
  .vue-portal-target a[class*="tsBody500"],
  .vue-portal-target a[class*="tsBodyControl500"] {
    color: var(--d-text) !important;
  }
  .vue-portal-target a:hover {
    color: var(--d-blue) !important;
  }
  /* Both rules below are scoped, because .vue-portal-target is a SHARED mount point:
     Ozon also portals the review media viewer (a separate `*_24` bundle) into it. An
     unscoped `.vue-portal-target svg` greyed that viewer's gold rating stars to the
     muted rail colour, and an unscoped `button svg` painted its close-X, prev/next
     arrows, play button and share glyph brand-blue — all invented colours on a surface
     that only exists after a click, so no load-time scan sees it.
     Every rail glyph the grey lift was written for sits inside an <a>; every flyout
     toggle carries the site bundle's own `uw_` class prefix, which the viewer's
     bundle does not. Specificity is deliberately kept BELOW the a[isload] and
     [data-widget="modalLayout"] rules further down, so those still win. */
  .vue-portal-target a svg {
    color: var(--d-text-4) !important;
  }
  .vue-portal-target button[class*="uw_"],
  .vue-portal-target button[class*="uw_"] span,
  .vue-portal-target button[class*="uw_"] svg {
    color: var(--d-blue) !important;
  }
  .vue-portal-target a[isload="true"],
  .vue-portal-target a[isload="true"] svg {
    color: var(--d-blue) !important;
  }
  /* Ozon also renders its DROPDOWN LISTS (the search-results sort menu, …) into
     this portal, and marks the currently-chosen option with a brand-blue tick it
     colours by INLINE `style="color: var(--graphicActionPrimary)"`. An inline
     declaration carries no !important, so the flyout's `svg { --d-text-4 }` rail
     rule above outranks it and greys the tick out — the "which option is active"
     signal, reduced to the same muted grey as every idle glyph. Match the inline
     token by name and give those glyphs the action blue back. */
  .vue-portal-target [style*="graphicActionPrimary"] {
    color: var(--d-blue) !important;
  }
  /* the currently-selected left-rail category paints a near-white pill
     (#f5f7fa via a hashed class, NOT a token) as its active highlight —
     a stark white box in the dark flyout. It only mounts on hover, so the
     page-load audit never sees it. It is uniquely the one loaded category
     (a[isload="true"]); repaint it to an elevated active dark surface so
     the highlight reads as a selection, not a white box. */
  .vue-portal-target a[isload="true"] {
    background-color: var(--layerActiveFloor0) !important;
  }
  /* FLYOUT STORE PICKER ("Весь Ozon" -> Ozon Банк / Билеты / Ozon Premium / …, the
     282px box above the category rail). Ozon paints its plate a literal near-white
     through a CLASS rule that covers BOTH states at once —
     `.uw_e7a.uw_ae8, .uw_e7a:hover { background: rgb(245,247,250) }` — so the
     inline-white neutraliser never sees it, and the plate sits four levels inside the
     portal, where the `.vue-portal-target > div` panel rule stops short. Every entry
     label is already lifted to light by the flyout link rules, so the OPEN list renders
     light-on-white: a dozen store names invisible. Hovering the collapsed box flashes
     the same white card. It exists only after two clicks, so nothing scans it at load.

     Reached by position — the rail column's only DIV child — instead of its rotating
     hash. The [class*="uw_"] guard pins this to the catalog-flyout bundle:
     .vue-portal-target is a SHARED mount, and the review media viewer's nodes at this
     depth carry the `_25` bundle prefix instead. The canvas colour, not an elevated
     one, because the four other flyout elements this depth reaches are natively
     transparent over the canvas — painting them the canvas is a no-op, painting them a
     surface would turn the whole category column into a slab. */
  .vue-portal-target > div > div > div > div[class*="uw_"] {
    background-color: var(--d-bg) !important;
  }
  /* REVIEW MEDIA VIEWER "Отзыв" BADGE — the pill laid over the top-left of each
     slide in the lightbox, carrying the label plus the reviewer's gold stars. Its
     label is a fourth --layerFloor1-as-WHITE-TEXT use (on the native rgba(7,7,7,.48)
     scrim), so our :root remap of that card-SURFACE token turns it #1c2128 on a
     near-black scrim — the stars stay gold beside a word that has vanished.

     Rebound on the slide rather than recoloured, because the label's own class is a
     rotating hash. Each slide carries Vue props leaked as plain lowercase attributes
     (uuid / reviewuuid / videoduration), which do NOT rotate with the build; measured
     live, no --layerFloor1 BACKGROUND use falls inside a slide, so rebinding it there
     repaints the label and nothing else. Mounts only on click, so no load-time scan
     sees it. */
  .vue-portal-target [reviewuuid] {
    --layerFloor1: #ffffff !important;
  }
  /* PORTAL ELEVATION SHADOWS — Ozon's is a PALE grey
     (`rgba(204,214,228,.6) 0 6px 16px 2px`), a soft drop shadow on the white site
     and a bright HALO on ours: it rings the review media viewer's whole 1120x612
     panel and its next/prev arrow discs with a visible light band. The colour is a
     literal outside the token system, so the remaps never reach it, and the viewer
     only exists after a click, so no load-time scan sees it. Measured live, every
     box-shadow anywhere in this portal is a light-site elevation cue that a dark
     surface no longer needs — the panel already separates from the dimmed page by
     value — so clear them rather than invent a dark shadow per shape. Restricted to
     DIVs on purpose: the viewer's own 48px arrow discs are <span>s carrying an
     already-dark rgba(0,26,52,.16) shadow, which stays. */
  .vue-portal-target div {
    box-shadow: none !important;
  }

  /* ------------------------------------------------------------
     PORTAL-MOUNTED MODALS (language/currency, address book, …). Ozon mounts
     these into the SAME .vue-portal-target as the catalog flyout, so the
     flyout rules above reach them. Three consequences, none of which any
     load-time scan can see — the modals only exist once opened:

       * the flyout's `button { color: blue }` (written for its "Еще"
         toggles) repaints each modal's PRIMARY CTA label our blue ON its
         brand-blue fill — blue-on-blue, ~1.3:1, the label all but gone.
         Modal CTAs are natively white-on-blue; restore that.
       * the currency/language modal's field labels ("Язык", "Валюта") ship
         a literal #070707 that the token remap never reaches, so they go
         near-black on the dark panel. They are the widget's only <p>.
       * the address modal lays its title OVER a LIGHT splash illustration
         (an <img>). Natively the title is near-black on that pale ground,
         but our `[class*="tsHeadline600Medium"]` shelf-heading rule lifts it
         to near-white -> light-on-light, fully invisible. The title box is
         the illustration's adjacent sibling, so keep it dark there ONLY.
     ------------------------------------------------------------ */
  .vue-portal-target [data-widget="modalLayout"] button,
  .vue-portal-target [data-widget="modalLayout"] button div,
  .vue-portal-target [data-widget="modalLayout"] button span {
    color: #ffffff !important;
  }
  [data-widget="currencyLanguageSelector"] p {
    color: var(--d-text) !important;
  }
  [data-widget="commonAddressBook"] img + div,
  [data-widget="commonAddressBook"] img + div span {
    color: #081b2b !important;
  }

  /* ------------------------------------------------------------
     BODY-MOUNTED MODAL PORTALS — Ozon mounts marketing / auth popups
     (e.g. the "Покупайте на Ozon как юридическое лицо" B2B modal) into a
     body-level [mountto="body"] wrapper, NOT a role="dialog", so the
     floating-surface dialog rule never reaches them. Their content panel
     ships literal #fff via hashed uw_* DIVs; the panel's own text is
     already lifted to light by the token/typography remaps, so on the
     white panel it goes light-on-light (invisible), and the panel is a
     stark white box on dark. The modal only mounts on interaction, so the
     load-time element-bg audit never sees it. Darken the panel DIVs to the
     elevated surface — this leaves the blue CTA and the white close-X
     (both <button>, not div) untouched, and the top promo banner (an
     image) unaffected — so the modal reads as a dark panel and its light
     text becomes legible. ---------------------------------------- */
  [mountto="body"] div[class*="uw_"] {
    background-color: var(--d-surface) !important;
  }
  /* The B2B "юридическое лицо" modal (and its siblings) list their benefit
     bullets ("Регистрация за 1 минуту", "Возврат до 20% НДС" …) in a literal
     near-black navy (rgb(8,27,43)) hardcoded outside the token system, so on the
     darkened panel the whole bullet column goes dark-on-dark (invisible) while the
     blue icons and CTA stay visible. tsBody500 is the bullet body copy; the
     tsBodyControl "Добавить компанию" CTA (white-on-blue) and the tsHeadline
     banner title are deliberately NOT matched, so they keep their colour. The
     modal only mounts on interaction, so a load-time scan never sees it. */
  [mountto="body"] div[class*="uw_"] span[class*="tsBody500"] {
    color: var(--d-text-2) !important;
  }

  /* ============================================================
     HEADER / NAV (data-widget="header") + sub-bars
     ============================================================ */
  [data-widget="header"],
  [data-widget="header"] > div,
  [data-widget="catalogMenu"],
  [data-widget="horizontalMenu"],
  [data-widget="addressBookBarWeb"],
  [data-widget="selectedCurrencyLanguage"],
  [data-widget="tapTags"] {
    background-color: var(--d-header) !important;
    color: var(--d-text) !important;
  }
  /* STICKY / AFFIXED HEADER (appears on scroll): Ozon mounts a
     position:fixed clone of the header whose OWN background is
     transparent but which paints a full-size WHITE panel through a
     ::before pseudo-element (background:#fff). Neutralising element
     backgrounds never reaches it, so on scroll the bar shows stark
     white behind the logo and around the right-hand icon cluster
     (the centre stays dark only because catalogMenu/search paint
     their own opaque surfaces over it). Repaint the header pseudo
     panel to the header chrome colour so the whole affixed bar is
     dark and its (already light) icons read.

     SCOPED to the header's own grandchild rows. An unscoped
     `[data-widget="header"] div::before` reaches EVERY div
     pseudo inside the header — including the search-suggest flyout,
     which is mounted inside <header>. Each suggest product tile has a
     full-size ::after overlay layer, so the broad rule painted an
     opaque --d-header panel over every product photo in the suggest
     panel (thumbnails rendered as blank dark boxes). Only the affixed
     bar's own ::before is ever white, and it is a grandchild of the
     widget, so scope there. */
  [data-widget="header"]::before,
  [data-widget="header"]::after,
  [data-widget="header"] > div::before,
  [data-widget="header"] > div::after,
  [data-widget="header"] > div > div::before,
  [data-widget="header"] > div > div::after {
    background-color: var(--d-header) !important;
  }

  /* HEADER CAMPAIGN BANNER — seasonal widgets (the Black-Friday counter, …)
     hang their artwork on a header-width div as an INLINE background-image
     PNG, and the top band of that artwork is white padding drawn to melt into
     the white header. The main-nav row sits over that band but is inset 24px
     inside the header, so once we darken the bar the padding surfaces as two
     ~24x25 white blocks flanking the row. It is raster paint: nothing
     hit-tests there and no element-background audit can see it.

     Redraw the band in the header colour with an inset shadow — inset shadows
     paint over the background image and under the content, so the banner text
     and CTA are untouched. 25px is exactly where the nav row ends, so the
     band's bottom edge lands on the row's, with no dark line across the art.

     Keyed on the inline background-image rather than the campaign's hashed
     class, so it survives the artwork rotating; a campaign that ships a dark
     background keeps its own art everywhere the header does not overlap. */
  [data-widget="header"] > div[style*="background-image"] {
    box-shadow: inset 0 25px 0 var(--d-header) !important;
  }

  /* MAIN-NAV ROW (data-widget="horizontalMenu") — Ozon renders each
     item's colour as an INLINE style, server-driven per item: the
     ordinary entries get `color:rgba(0, 26, 51, 0.6)` (dark navy,
     invisible on our dark bar) while "Ozon fresh" gets its brand teal
     `color:#00a6a6`. An inline value beats any class rule, and a
     blanket `[data-widget="horizontalMenu"] a { color }` would erase
     the teal along with the navy.

     Match the navy inline value literally, so only those items lift — in BOTH
     serialisations. Ozon's server-rendered markup ships the value minified
     (`color:rgba(0, 26, 51, 0.6)`), but as soon as Vue re-renders the header
     client-side (apply a filter on a category page and it happens immediately)
     it re-writes the same declaration through the CSSOM, which serialises with
     a space after the colon. A single-form attribute-substring match therefore
     stops matching mid-session and the ENTIRE main-nav row drops back to navy
     on the near-black bar — invisible. Both literals are needed.

     The glyphs then need `color: inherit` — Ozon paints them
     `fill: currentColor` but pins that currentColor with its OWN
     literal navy class rule, so they do not follow the item's colour
     on their own. Inheriting reaches "Для бизнеса" (a <button>, which
     every `… a svg` rule structurally missed, leaving its briefcase
     dark-on-dark) AND leaves the Ozon-fresh leaf teal, because it
     inherits that item's teal. No brand special-case needed. */
  [data-widget="horizontalMenu"] [style*="color:rgba(0, 26, 51, 0.6)"],
  [data-widget="horizontalMenu"] [style*="color: rgba(0, 26, 51, 0.6)"] {
    color: var(--d-text) !important;
  }
  [data-widget="horizontalMenu"] a svg,
  [data-widget="horizontalMenu"] a span,
  [data-widget="horizontalMenu"] button svg,
  [data-widget="horizontalMenu"] button span {
    color: inherit !important;
  }
  [data-widget="horizontalMenu"] a:hover,
  [data-widget="horizontalMenu"] button:hover {
    color: var(--d-blue-hover) !important;
  }

  /* ------------------------------------------------------------
     OZON FRESH category sub-nav (data-widget="horizontalCategoryMenu")
     — the horizontal category row on the Ozon Fresh landing page
     (ПРОДУКТЫ / ДЛЯ МАМ И ДЕТЕЙ / КРАСОТА И ЗДОРОВЬЕ / …). Ozon
     ships its wrapper as a literal WHITE bar (rgb(255,255,255)) with
     near-black label links (rgb(7,7,7)); it only appears on this
     Fresh variant, so the home/PDP audits missed it. Darken the bar
     to the elevated surface and lift the labels to readable light;
     hover/active brighten. ------------------------------------- */
  [data-widget="horizontalCategoryMenu"],
  [data-widget="horizontalCategoryMenu"] > div,
  [data-widget="horizontalCategoryMenu"] nav,
  [data-widget="horizontalCategoryMenu"] ul {
    background-color: var(--d-surface) !important;
    border-color: var(--d-border) !important;
  }
  /* The row's overflow toggle ("Еще") is a <button>, not an <a>, and the site pins
     it at a literal rgb(7,7,7) outside the token system. Its LABEL is a <span> and
     so was already lifted — but the chevron beside it is `fill="currentColor"`, so
     it kept inheriting the button's near-black and rendered as an all-but-invisible
     glyph on the bar. The label reading fine is exactly what hides this: nothing
     looks broken until you crop the 24px chevron. Lift the button itself and the
     glyph follows. */
  [data-widget="horizontalCategoryMenu"] a,
  [data-widget="horizontalCategoryMenu"] li,
  [data-widget="horizontalCategoryMenu"] span,
  [data-widget="horizontalCategoryMenu"] button {
    color: var(--d-text-2) !important;
  }
  [data-widget="horizontalCategoryMenu"] a:hover,
  [data-widget="horizontalCategoryMenu"] a:hover span,
  [data-widget="horizontalCategoryMenu"] li:hover,
  [data-widget="horizontalCategoryMenu"] a[aria-current],
  [data-widget="horizontalCategoryMenu"] a[aria-current] span {
    color: var(--d-text) !important;
  }

  /* ------------------------------------------------------------
     CATEGORY TILE ROWS (data-widget="objectLine") — the illustrated
     shortcut tiles on the Ozon Fresh landing ("Продукты Ozon fresh",
     "Готовая еда", "Овощи, фрукты, зелень" …) and the same widget wherever
     else it appears. The tile art is a CDN jpeg with its own light ground,
     but the CAPTION under it sits on the page canvas and is painted a literal
     rgb(7,7,7) by the tile component — outside the token system, so the
     :root remap never reaches it. Thirty-five captions render near-black on
     near-black: the row reads as a strip of pictures with no labels at all.

     Scoped to the caption's typography class rather than a blanket on the
     anchor: every other div inside these tiles is an empty wrapper inheriting
     the action blue, and repainting those would strip currentColor from any
     glyph they carry. Measured live, this selector matches the 35 captions and
     nothing that was carrying a colour of its own. ------------------------ */
  [data-widget="objectLine"] a [class*="tsBody"] {
    color: var(--d-text) !important;
  }

  /* ------------------------------------------------------------
     BRAND SHELF (data-widget="objectThumbnailList") — the "Популярные бренды"
     row on category / Ozon Fresh landings. Its CMS text component pins a literal
     rgb(7,7,7) on BOTH the section heading and every brand caption, outside the
     token system, so the :root remap never reaches either. On the darkened island
     card that is ~1.1:1 — the heading and all twenty brand names go fully
     invisible while the logo tiles above them still read, so the row looks like
     an unlabelled strip of logos with no title.

     The heading needs the CHILD selector: the site puts tsHeadline600Medium on
     the WRAPPER and the colour on the wrapper's inner div, so the theme's own
     `[class*="tsHeadline600Medium"]` rule only reaches the wrapper and the inner
     declaration wins (inherited colour never beats a direct one). Both rules are
     scoped to the widget, whose hashed CMS classes (q4b1_5_6-*, uw_za9) rotate
     every build. ------------------------------------------------------------ */
  [data-widget="objectThumbnailList"] [class*="tsHeadline"] > div {
    color: var(--d-text) !important;
  }
  [data-widget="objectThumbnailList"] a p {
    color: var(--d-text-2) !important;
  }
  /* …and that caption rule, being !important, also swallowed the shelf's only hover
     feedback: natively a brand caption flips from the literal near-black to Ozon's
     pressed blue #0050e0 under the cursor, so with both states pinned to one grey
     the whole row of twenty tiles answers the mouse with nothing. Invisible to both
     scanners — a state that is not rendered cannot be scanned — and found by a
     native-vs-themed hover diff. Lifted to the theme's hover blue rather than the
     site's #0050e0, which is only ~2.6:1 on our canvas: the same substitution the
     filter-rail / breadcrumb / footer hovers already make. The sibling
     objectLine captions are deliberately NOT given a hover — measured live, they
     have none natively either. */
  [data-widget="objectThumbnailList"] a:hover p {
    color: var(--d-blue-hover) !important;
  }

  /* CATALOG MEGA-MENU text: the flyout's section headings and its
     category links are BOTH <a>, and natively differ (headings are
     --textPrimary near-black, links are --textSecondary grey). The
     tokens colour them correctly; nothing to override. Only the
     heading weight distinguishes them, exactly as on the light site. */

  /* ============================================================
     SEARCH BAR + INPUT  (data-widget="searchBarDesktop")
     ============================================================ */
  [data-widget="searchBarDesktop"] {
    background-color: transparent !important;
  }
  [data-widget="searchBarDesktop"] input,
  input[type="text"],
  input[type="search"],
  textarea {
    background-color: var(--d-surface) !important;
    color: var(--d-text) !important;
    border-color: var(--d-border-2) !important;
  }
  /* SEARCH-BAR FRAME — the search area is wrapped in Ozon's signature
     2px brand-blue border (#005bff). Our blanket `* { border-color }`
     softener flattens it to grey, erasing the single most recognisable
     brand element in the header (chroma-scan flagged it: native blue
     chroma 255 -> our neutral grey). The frame is the one direct DIV
     child of the search form; lift its border back to the refined dark
     Ozon blue so the search bar reads as Ozon on the near-black bar. */
  .search-bar-wrapper form > div {
    border-color: var(--d-blue) !important;
  }
  [data-widget="searchBarDesktop"] input::placeholder,
  input::placeholder,
  textarea::placeholder {
    color: var(--d-text-3) !important;
    opacity: 1 !important;
  }
  /* autocomplete / suggest dropdown — must be opaque dark */
  [data-widget="searchBarDesktop"] ul,
  [data-widget="searchBarDesktop"] [role="listbox"] {
    background-color: var(--d-surface) !important;
    border-color: var(--d-border) !important;
  }
  /* SEARCH SUGGEST FLYOUT — Ozon renders the autocomplete/suggest
     panel from its search CSS module (.search_* classes) OUTSIDE the
     searchBarDesktop widget, with a TRANSPARENT background. On the
     light site that simply showed the white page behind it; on dark
     the panel lets colourful home banners / hero images bleed THROUGH
     the suggestion list (floating-surface bleed-through). The .search_
     prefix is the module name (stable across builds; only the hash
     suffix rotates). Give the flyout panel a solid opaque dark backing
     so the query suggestions + product previews read on every page.

     SCOPED to .search-bar-wrapper: an unscoped `div[class*="search_"]`
     also matched the flyout's full-viewport SCRIM (a position:fixed
     z-501 sibling that lives OUTSIDE the wrapper and is natively a
     translucent rgba(3,8,13,.32) dim). Painting that opaque blanked the
     whole page behind the suggest panel. The scrim keeps its own dim.

     KNOWN LIMIT: this neutraliser, together with the widget-wide
     `[data-widget="searchBarDesktop"] div { transparent }` above, also flattens the
     SEARCH-SCOPE CHIP ("Ozon fresh ✕" — the pill shown when a query is restricted to
     a store or category), whose applied state is natively a solid #005bff fill. Idle
     it is only rgba(0,48,120,.04), so idle-vs-flat is a non-difference; applied loses
     its brand fill. Active and idle differ ONLY by a content-hashed modifier class,
     and an !important background cannot be handed back to the site once declared, so
     restoring it would mean betting on a hash that rotates every build. Left as is:
     the applied scope is still carried by the label plus its ✕ remove button. */
  .search-bar-wrapper div[class*="search_"] {
    background-color: var(--d-bg) !important;
  }
  /* COUNTRY-CODE SELECTOR (OZON ID login modal — a same-origin
     www.ozon.ru/ozonid-lite iframe, so the theme applies inside it).
     The phone field's country picker renders the flag + dial code
     ("+7"/"+33") on a dark button, with a searchable dropdown driven by
     a role="combobox" name="filter" text input laid OVER the collapsed
     button to capture keystrokes. Our generic input background rule
     painted that overlay input opaque (--d-surface), covering the dial
     code so the box looked empty (the code text is light but hidden
     BEHIND the opaque overlay — an audit-blind overlapping-input miss;
     only elementsFromPoint reveals it). The main search input is
     name="text", so scoping to name="filter" avoids any collision.
     Make the overlay transparent so the dial code reads; typed filter
     text still shows light on the button's dark surface. */
  input[role="combobox"][name="filter"] {
    background-color: transparent !important;
  }
  /* SEARCH-RESULTS SORT CONTROL ("Популярные" / "Сначала дешёвые" …). The
     control is a readonly text <input> that fills the full height of a 230px
     shell the site outlines with its own 1px inset ring
     (rgba(204,214,228,.6) — native, not ours) and leaves the last 44px for the
     chevron. The input is natively TRANSPARENT; our generic text-input
     background paints it opaque, which covers the ring's left, top and bottom
     edges and renders the control as a half-drawn outline hugging the chevron.
     Element-background audits pass — every colour involved is a legitimate
     dark — and only the pixels show it. The shell already carries the elevated
     surface, so hand the input its native transparency back. */
  [data-widget="searchResultsSort"] input {
    background-color: transparent !important;
  }

  /* ============================================================
     PRODUCT TILES / CARDS  (.tile-root, tileGridDesktop)
     ============================================================ */
  [data-widget="tileGridDesktop"],
  [data-widget="searchResultsV2"],
  [data-widget="skuGrid"],
  [data-widget="skuShelfGoods"] {
    background-color: transparent !important;
  }
  .tile-root,
  .tile-hover-target,
  [data-widget="tileGridDesktop"] .tile-root {
    background-color: var(--d-surface) !important;
    border-color: var(--d-border) !important;
  }

  /* DISCOUNT pill + its scroll-fade, and the cart line-item image plate. Ozon
     renders the "−NN%" badge with an INLINE `background: var(--bgLightKey)` and
     prepends a 6px fade div carrying an inline
     `background: linear-gradient(to right, transparent, var(--bgLightKey))`
     that masks the strikethrough price as it scrolls under the badge.
     --bgLightKey is literal #fff, so on dark the badge sat on a white pill and
     the fade rendered as a bright bar across the price row. A
     `background-color: transparent` override cannot clear the fade (it is a
     background-IMAGE) — element-bg audits pass clean while the bar glares.

     Keyed on the INLINE DECLARATION, not on a container. The same badge+fade
     pair ships in every product surface — tile grids, PDP shelves, AND the cart
     line items, which are not .tile-root — so a card-scoped rebind covers only
     the one component it was written against and the cart shipped two white bars
     per price row. Both serialisations carry the identical `var(--bgLightKey)`
     substring, so one match covers server-rendered and CSSOM-rewritten markup.

     The token must NOT be rebound at :root: the shared button component also
     reads it as `--hover-background-color`, where it is a 10%-opacity WHITE veil
     that LIGHTENS a button on hover (Каталог, tile CTAs, review-helpful votes,
     the cookie bubble …). A dark value there is a 10% veil of the surface colour
     over the surface colour, i.e. no hover feedback at all, site-wide. */
  [style*="var(--bgLightKey)"] {
    --bgLightKey: var(--d-surface) !important;
  }
  .tile-root span,
  .tile-root a,
  .tile-root div {
    border-color: var(--d-border) !important;
  }

  /* ============================================================
     CARD / PRODUCT TEXT — nothing to force here. Card text (title,
     rating, review count, "N шт осталось", brand, "Оригинал") is
     coloured by --textPrimary / --textSecondary / --textTertiary,
     and the semantic bits by --textAccent (pink −NN%),
     --textPositive (green Ozon-card price) and --grSale (the
     orange->magenta gradient-clipped sale price). All are remapped
     at :root, so they render light-on-dark WITH their meaning intact.

     The rules that used to live here forced .tile-root ts* text to
     one of two neutral greys. That flattened, on every card: the
     pink −NN%, the white label on the pink "Распродажа" pill and the
     violet "баллы за отзыв" pill, the Ozon-card green price, the blue
     "Ozon" seller mark, and the sale price's gradient — while every
     contrast threshold still passed, because grey on dark is legible.
     ============================================================ */

  /* ============================================================
     PRODUCT DETAIL PAGE (PDP)
     ============================================================ */
  /* PDP text (title, breadcrumbs, spec labels/values, SKU/share/compare,
     review lines) is coloured through --textPrimary/Secondary/Tertiary,
     remapped at :root — no per-widget text override needed. The blanket
     that used to sit here (`webPdpGrid span, div, p, li, h1…`) also
     erased the PDP's semantic colours: the green --textPositive
     Ozon-card price, the pink --textAccent discount, and the blue
     --textAction "Перейти в магазин" / seller links. */

  /* TITLE TRUNCATION FADE — when the product name is long enough to
     clip, Ozon appends a "…ещё" (show more) toggle whose wrapper paints
     a horizontal linear-gradient ::before that fades the last line of
     text into the page background (…transparent -> #fff). On the light
     site that blended into the white page; on dark it renders a stark
     WHITE smear across the end of the title. The gradient is a
     background-IMAGE with a transparent background-color, so the
     element-bg audit passes clean (it only mounts when the title is
     truncated, so short-title PDPs never show it). Remap the fade to the
     base canvas so it blends into the dark page instead of flashing
     white. Only one heading ::before ever carries a background-image (this
     fade), so scoping to the widget's pseudos is safe. */
  [data-widget="webProductHeading"] *::before {
    background-image: linear-gradient(
      90deg,
      rgba(20, 24, 29, 0),
      var(--d-bg) 57%
    ) !important;
  }

  /* PDP white delivery/seller panels: repaint the panel surface dark
     (they ship literal #fff via hashed classes). Restricted to DIVs:
     the "В корзину" primary CTA is a <button class="pdp_f1a">, and an
     element-agnostic `[class*="pdp_"]` neutraliser stripped its brand
     blue fill, leaving a white label floating on the page with no
     button behind it. A flattened CTA still passes every contrast
     check, so no scan reported it.

     The `:not([style*="background"])` guard matters just as much: Ozon paints
     its coloured BADGE pills with an INLINE background (the violet "Оплатить
     позже" chip = `background: var(--bgMarketingPrimary)`, the violet marketing
     label = `background-color: var(--textMarketing)`, the "250 баллов за отзыв"
     pill = a literal rgb(91,81,222)). Those pills are DIVs with a pdp_/module
     class, so the blanket swallowed their fill and left the label floating as
     bare text on the page — a lost brand signal that every contrast check
     passes. Never flatten a background Ozon explicitly asked for inline. */
  [data-widget="webPdpGrid"] div[class*="pdp_"]:not([style*="background"]) {
    background-color: transparent !important;
  }

  /* OZON-CARD PRICE PILL — the buybox headline price sits on a solid GREEN pill
     (#00c451, white text): Ozon's "this is the price with an Ozon card" signal,
     and the single most prominent semantic colour on the PDP. It carries NO
     inline style and no stable class (its `pdp_gb2` hash rotates every build),
     so the neutraliser above flattened it and the price became plain light text
     on the dark panel — indistinguishable from the ordinary bank price beneath
     it. Its price <span> IS uniquely reachable: it is the only
     tsHeadline600Large in the widget. Repaint the pill on that span, mirroring
     the native geometry (radius 8px, padding 2px 8px) and cancelling the added
     box with an equal negative margin so nothing shifts. */
  [data-widget="webPrice"] span[class*="tsHeadline600Large"] {
    background-color: #00c451 !important;
    color: #ffffff !important;
    border-radius: 8px;
    padding: 2px 8px;
    margin: -2px -8px;
  }

  /* PDP title truncation "…ещё" pill ships `background: var(--graphicLightKey)`
     = literal #fff, so it renders a WHITE box on the dark product title.
     --graphicLightKey is NOT remapped at :root on purpose: it is a CONTEXT-named
     "light key" the site also uses as `color:`/`--icon-color`/`--loader-color`
     for WHITE text and glyphs on dark/coloured grounds (the .b5_7_0-a5 story
     labels, loaders, icons). A :root lift would flip all of those dark-on-dark.
     So rebind the token inside the heading widget only, where its single use is
     this pill's background: an opaque pill that masks the clamped text edge and
     blends into the canvas, matching the native white-on-white (invisible) pill.

     Rebinding the TOKEN rather than naming the pill matters: the pill used to be
     reachable as `span.pdp_h5b`, but Ozon has since moved the white background
     one level in, onto an inner `span.pdp_b6h` while `pdp_h5b` became a plain
     DIV wrapper — so the class-keyed rule silently stopped matching and the
     white box came back on every truncated-title product page. The token is the
     one handle in this component that does not rotate with the build. */
  [data-widget="webProductHeading"] {
    --graphicLightKey: var(--d-bg) !important;
  }

  /* MAIN CTA BUTTON (В корзину) — a genuine brand-coloured button; keep
     its label bright white on the blue fill. The secondary buttons
     (Купить сейчас / Оплатить позже) are NOT included: they ship a
     translucent-blue ground with blue --textAction label, and forcing
     white on them erased the primary/secondary distinction. */
  [data-widget="webAddToCart"] button,
  [data-widget="webAddToCart"] button span {
    color: #ffffff !important;
  }

  /* Review tiles (pinnedReview / webReviewGallery / bigPromoPDP) ship a
     white card surface; drop it so they sit on the page canvas. Their
     text is token-coloured and needs no override.

     Same INLINE-BACKGROUND guard as the PDP grid and gallery resets, and for the
     same reason. webReviewTabs is not just the review cards: Ozon nests a whole
     product shelf (skuGrid of .tile-root tiles) inside it, and every tile badge
     paints its fill with an inline `background: rgb(...)` — the pink
     "Распродажа", the violet "N баллов за отзыв", the black "Вау-цены". The
     unguarded reset outranked those inline declarations and left ten pills as
     bare white labels floating on the tile, while the IDENTICAL tiles in the
     shelf above them (outside the review widget) kept their pink. Flattened
     brand fills pass every contrast and DOM check — only a native-vs-themed
     colour diff sees them. Never flatten a background Ozon asked for inline. */
  [data-widget="pinnedReview"],
  [data-widget="pinnedReview"] div:not([style*="background"]),
  [data-widget="webReviewGallery"],
  [data-widget="webReviewGallery"] div:not([style*="background"]),
  [data-widget="webReviewProductScore"] div:not([style*="background"]),
  [data-widget="webReviewTabs"] div:not([style*="background"]),
  [data-widget="bigPromoPDP"],
  [data-widget="bigPromoPDP"] div:not([style*="background"]) {
    background-color: transparent !important;
  }
  /* REVIEW-SCOPE SEGMENTED CONTROL ("Все отзывы" / "Этот вариант товара (188)").
     Ozon builds it as a recessed #f5f7fa track with the ACTIVE segment raised on a
     white pill; that pill is the control's only state signal — both labels are the
     same near-black weight natively. The webReviewTabs reset above nests it, so it
     flattens the track AND the pill, and the control ships as two identical labels
     floating on the page with nothing marking which scope the review list is showing.
     Legible dark text either way, so no contrast, DOM or chroma check flags it.

     The active segment carries a modifier class on top of the shared segment class,
     while the idle one carries the shared class alone — so `[class*=" "]` (a class
     attribute holding more than one name) names the active segment at any build,
     without pinning the modifier's rotating hash. Both segments are `div[tabindex]`.
     Track and pill are given two distinct elevations so the raised-vs-recessed
     relationship survives the inversion. */
  [data-widget="webReviewsVariantMode"] > div[class] {
    background-color: rgba(255, 255, 255, 0.06) !important;
  }
  [data-widget="webReviewsVariantMode"] div[tabindex][class*=" "] {
    background-color: var(--layerActiveFloor1) !important;
  }
  /* PINNED-REVIEW CLAMP FADE — the pinned review card clamps its body copy and
     fades the last two lines out under a 50px-tall ::after carrying
     `linear-gradient(0deg, rgb(235,239,245), transparent)`. The stop is a
     hardcoded near-white literal, outside the token system, so nothing above
     reaches it: on dark it washes the bottom third of the card pale grey and
     takes the final lines of the review with it. It is a background-IMAGE on a
     PSEUDO, so both the element-bg reset above and any element walk pass clean.
     Measured live, this is the ONLY rendered pseudo anywhere in the widget, so
     re-aiming the widget's ::after gradient hits the fade and nothing else. The
     card is transparent on the page canvas, so the fade ends at the base. */
  [data-widget="pinnedReview"] *::after {
    background-image: linear-gradient(
      0deg,
      var(--d-bg),
      rgba(20, 24, 29, 0)
    ) !important;
  }
  /* "+N" MORE-PHOTOS OVERLAY on the last thumbnail of a review's photo strip.
     Natively an rgba(255,255,255,.8) veil over the whole tile carrying a big blue
     count — "there are N more photos here". It carries no inline background, so
     the reset above (correctly) clears it, leaving the count as bare #005bff text
     directly on the photo: ~2.9:1, no plate, and the "more" affordance gone. Give
     it the dark-side equivalent — a near-black veil with a white count — mirroring
     what the video-timecode scrim does two rules down. `:not([style])` keeps the
     inline-styled timecode pill in the same button family untouched. */
  [data-widget="webListReviews"] button[aria-label="Открыть галерею"] > div:not([style]) {
    background-color: rgba(7, 7, 7, 0.64) !important;
    color: #ffffff !important;
  }
  /* REVIEW-LIST ACTION TEXT that is not an <a>: the "Читать полностью" expander on
     every clamped review, and the "+N" photo count, both colour themselves with
     `color: var(--bgActionPrimary)` — a token NAMED for the blue CTA fill but
     reused here as text. It stays the raw #005bff, ~2.9:1 on the base, sitting
     right beside the review's own links which the rule above lifts to #2e78ff:
     the same widget shipping two different blues, one of them below the WCAG
     floor. --bgActionPrimary cannot be lifted at :root (17 of its uses are button
     FILLS, where white-on-#2e78ff drops to 3.4:1), so rebind it inside this widget
     only — measured live, it repaints exactly these text uses and no fill. */
  [data-widget="webListReviews"] {
    --bgActionPrimary: var(--d-blue) !important;
  }
  /* REVIEW RATING HISTOGRAM ("5 звёзд … 1 звезда" bars): the webReviewTabs
     `div { transparent }` reset above flattens BOTH the grey track and the gold
     proportion fill, so the distribution bars vanish (only the counts remain).
     Ratings are a kept-brand surface, so restore the gold fill. The fill is the
     only descendant carrying an inline PERCENT width (the track/underline use px),
     so this matches exactly the five bars and never the blue tab underline.

     webReviewProductScore is the SAME control on the standalone /reviews/ page,
     where the score summary is its own widget instead of a webReviewTabs panel —
     and it carries its own copy of the `div { transparent }` reset, so the fills
     were flat there while the PDP's were gold. The track stays visible on that
     page, which is exactly what hides it: five identical grey bars still look
     like a chart, so 869 five-star and 1 two-star read the same.

     The grey TRACK behind the fill is flattened by the same reset and has no
     selector of its own — it is the fill's PARENT, hashed, attribute-less. It does
     carry `overflow: hidden` with a 5px radius, so a large-spread box-shadow on the
     fill paints the remainder and is clipped to exactly the track's rounded box.
     That also keeps a bar visible for a rating with zero reviews, whose fill is
     0px wide. */
  [data-widget="webReviewTabs"] div[style*="width"][style*="%"],
  [data-widget="webReviewProductScore"] div[style*="width"][style*="%"] {
    background-color: var(--d-gold) !important;
    box-shadow: 0 0 0 300px rgba(255, 255, 255, 0.12) !important;
  }
  /* Each histogram row spaces itself from the next with a 6px `border-bottom` that
     is natively TRANSPARENT — a border used as a gap, not as a line. The blanket
     `* { border-color }` softener at the top of this file paints it --d-border, so
     a fat grey bar appears under every rating row: the chart renders as ten bars
     where the site draws five, and the phantom ones are thicker than the real ones.
     Nothing flags it — the colour is a legitimate theme value, the element has no
     background, and the native side reads `rgba(0,0,0,0)`, which every "is it light?"
     test passes.

     Cleared across the whole widget rather than aimed at the rows: the histogram
     list sits at a different depth on the PDP (where an extra summary block precedes
     it) than on the standalone /reviews/ page, so any nth-child path that names the
     rows on one page names a wrong element on the other. The widget's only other
     bottom border is the 1px hairline under the stars header, which sits at that same
     shifting depth and so goes with them; the header is still set off by its own
     spacing, and one lost hairline beats five phantom bars. */
  [data-widget="webReviewProductScore"] div {
    border-bottom-color: transparent !important;
  }
  /* ACTIVE review-tab underline ("Отзывы о товаре" / "Вопросы о товаре"): a 2px bar
     Ozon slides under the current tab, painted brand-blue via an inline left+width.
     The same `div { transparent }` reset flattens it away, so the active tab keeps
     only its bold weight and loses the brand accent. It is the ONLY inline-styled
     div carrying both `left` and `width` (the gold histogram fills carry width
     only), so it is reachable without the % the histogram rule keys on. */
  [data-widget="webReviewTabs"] div[style*="left"][style*="width"] {
    background-color: var(--d-blue) !important;
  }

  /* SELLER RICH-CONTENT DESCRIPTION (data-widget="webDescription", built from the
     "Rich Annotation" RA-* module) hardcodes a near-black navy (rgb(0,26,52)) on its
     body copy, outside the token system — so the whole product-description paragraph
     renders dark-on-dark (invisible) on the dark panel. The block's headings and
     accents are baked into <img> banners, not DOM text, so lifting the RA text to the
     body scale only touches the paragraph copy (already-light RA text stays light).
     The block lazy-mounts far down the PDP, so a load-time scan never sees it. */
  [data-widget="webDescription"] [class*="RA-"] {
    color: var(--d-text-2) !important;
  }

  /* GALLERY: the stage + thumbnail tiles are white CONTAINERS
     behind/around the photo. Darken the container, not the <img>.
     pdp_* are hashed but the gallery is most reliably reached
     structurally via the widget; repaint any white wrapper inside. */
  [data-widget="webGallery"] {
    background-color: transparent !important;
  }
  /* Same inline guard as the PDP grid: Ozon overlays the gallery with its
     marketing-label chips (webMarketingLabels), which paint a violet fill via an
     INLINE `background-color: var(--textMarketing)`. Those chips are DIVs inside
     the gallery, so an unguarded reset erased the pill and left the label as bare
     text over the photo. */
  [data-widget="webGallery"] div:not([style*="background"]),
  [data-widget="webListPhotos"] div:not([style*="background"]) {
    background-color: transparent !important;
  }
  /* GALLERY "Похожие" PILL — the visual-search affordance Ozon floats over the main
     product photo. Natively a solid WHITE pill with rgba(0,26,51,.6) navy text; the
     inline-guarded gallery reset above strips the plate (it carries no inline
     background) while the token remap lifts the label to light — leaving pale grey
     text with no plate directly on a LIGHT product photo, effectively invisible.
     It is the only tsBodyControl500Medium in the widget, so it is reachable without a
     rotating pdp_ hash. Give it back an opaque plate, inverted for dark.
     The webPdpGrid ancestor is in the selector for SPECIFICITY, not scoping: the
     grid-wide `div[class*="pdp_"]:not([style*="background"])` neutraliser above also
     matches this pill, and a webGallery-only selector merely TIES with it. */
  [data-widget="webPdpGrid"] [data-widget="webGallery"] div[class*="pdp_"][class*="tsBodyControl500Medium"] {
    background-color: var(--d-surface) !important;
    color: var(--d-text) !important;
  }
  /* product photos sit on white in the source; give the photo
     frame a soft light mat so cut-out PNGs stay legible, but the
     surrounding stage/thumbnail strip stays dark */
  [data-widget="webGallery"] img,
  [data-widget="webListPhotos"] img,
  .tile-root img {
    background-color: #f3f5f8 !important;
    border-radius: 6px;
  }
  /* Gallery media-count label ("+2 видео") under the video thumbnail hardcodes the
     raw brand blue #005bff (~2.9:1 on the base, below the WCAG floor); the token
     lift never reaches it. Lift to our refined blue. */
  [data-widget="webGallery"] div.pdp_s4a {
    color: var(--d-blue) !important;
  }

  /* ============================================================
     FLOATING / STICKY SURFACES — must stay SOLID opaque dark so
     content doesn't bleed through on scroll. Covers sort bar,
     sticky buybox, sticky add-to-cart, modals, dropdowns, popovers.
     ============================================================ */
  /* SELECTED filter chips reuse Ozon's primary-button component:
     `background: var(--ozCtrlPrimary); color: var(--ozTextPrimaryNegative)`.
     --ozCtrlPrimary is dual-use (5 text rules, 2 fill rules), so it is
     globally lifted to our brighter blue for the TEXT cases — but on a
     FILL that lift drops the white chip label to 3.4:1. Rebind the token
     back to the native brand blue inside this fill-only widget: white on
     #005bff is 5.4:1, and the chip stays unmistakably Ozon-blue. */
  [data-widget="searchResultsFiltersActive"] {
    --ozCtrlPrimary: #005bff !important;
  }

  [data-widget="searchResultsSort"],
  [data-widget="searchResultsFiltersActive"],
  [data-widget="webStickyProducts"],
  [data-widget="stickyContainer"],
  [data-widget="webChatButton"],
  [class*="sticky"],
  [role="dialog"],
  [role="menu"],
  [role="listbox"],
  [role="tooltip"] {
    background-color: var(--d-header) !important;
    color: var(--d-text) !important;
    border-color: var(--d-border) !important;
  }
  /* ============================================================
     FILTERS / LEFT RAIL  (data-widget="filtersDesktop")
     audit all states: default label, hover, checked.
     ============================================================ */
  [data-widget="filtersDesktop"],
  [data-widget="filtersDesktop"] div {
    background-color: transparent !important;
  }
  /* The left-rail "Категория" / sort card paints its white panel through a
     full-size ::before pseudo-element on the <aside> wrapper (a hashed class,
     background:#fff), NOT on the element's own background — so neutralising the
     element backgrounds above leaves the card stark WHITE. Repaint every
     filter-rail pseudo layer to the elevated dark surface so the card reads as
     a panel instead of a bright box. */
  [data-widget="filtersDesktop"] *::before,
  [data-widget="filtersDesktop"] *::after {
    background-color: var(--d-surface) !important;
  }
  /* BRAND-LOGO CHECKBOXES (Xiaomi / Apple / Poco / … in the Бренд filter) render
     the logo as an <img> inside a checkbox box that carries a full-size,
     natively near-transparent ::after overlay. The rule above repaints that
     overlay to an OPAQUE elevated surface, which sat ON TOP of the logo and
     blanked every brand tile to an empty dark square (the logo bitmap still
     paints — canvas-samples orange for Xiaomi — it is simply covered). The
     ::after is a positioned pseudo, so lift the logo images into their own
     positive stacking layer to paint above it. Filter images are only these
     brand/store logos, which carry their own light ground, so no mat needed. */
  [data-widget="filtersDesktop"] img {
    position: relative !important;
    z-index: 1 !important;
  }
  /* CURRENT CATEGORY in the "Категория" rail — Ozon marks the page you are on with
     a pale #f5f7fa pill behind its row; the ancestor rows above it carry a back
     chevron and its child categories below it carry nothing. The `div { transparent }`
     neutraliser above erases that pill, so the current category becomes
     indistinguishable from the children listed under it: the rail loses its only
     "you are here". Neither scanner sees it — the pill is a neutral grey, so chroma
     has no hue to miss, and a flattened highlight is still a legible link.

     The row is reachable without betting on a hash. Ozon adds a modifier class to
     the CURRENT row only; every other category row ships `class=""`, and the section
     header and the "Посмотреть все" action carry no inline margin. So "a category
     row whose class attribute is not empty" names the current one exactly, at any
     tree depth, while the modifier's own hash rotates freely. Verified on a
     top-level, a mid-level and a leaf category. Repainted to the same active
     elevation the catalog flyout's loaded rail category uses. */
  [data-widget="filtersDesktop"] div[style*="margin-left"][class]:not([class=""]) {
    background-color: var(--layerActiveFloor0) !important;
  }

  /* TOGGLE SWITCHES in the rail ("Распродажа", "Бренд проверен", "Официальные
     магазины бренда") — a 44x28 pill whose track is the input's ADJACENT SIBLING
     div and whose knob is that div's ::before. Two of our own rail resets erase the
     control whole: the `div { transparent }` neutraliser above clears the track
     (natively rgba(204,214,228,.6)) and the `*::before { --d-surface }` pseudo
     repaint turns the white knob into #1c2128. An OFF switch therefore renders as
     literally nothing — no track, no knob, no hint the row is a control at all,
     while the label beside it reads perfectly, which is exactly what hides it. The
     lock glyph inside the knob keeps its native dark rgba(0,26,52,.4), and that is
     right only once the knob is light again.

     The switches are the one input kind in the rail with NO `name` attribute — the
     checkboxes, radios and price-range fields all ship `name=""` — so they are
     reachable with no hashed class. Specificity is deliberately held at (0,2,2),
     level with the `input:checked + div` fill rule below, so a CHECKED switch still
     takes the brand blue from that rule, which wins on source order. Adding
     [type="checkbox"] here would outrank it and grey out every checked switch. */
  [data-widget="filtersDesktop"] input:not([name]) + div {
    background-color: rgba(255, 255, 255, 0.16) !important;
  }
  [data-widget="filtersDesktop"] input:not([name]) + div::before {
    background-color: #ffffff !important;
  }
  /* CHECKED filter radio / checkbox — Ozon fills the selected control with its
     brand blue (#005bff) and draws the dot/tick in white on top of it. The
     `div { transparent }` neutraliser above flattens that fill away, so a
     CHECKED filter renders as a bare white dot, indistinguishable in kind from
     the unchecked rings: the selection signal is gone while every contrast
     threshold still passes (the chroma scan flagged it — native chroma 255 ->
     transparent). The control's visual box is the input's ADJACENT SIBLING, so
     the checked ones are reachable without a hashed class. Restore the native
     #005bff: this is a FILL, not text, so the brand blue is correct here (the
     lifted --d-blue is for text on near-black) and keeps its white glyph legible. */
  [data-widget="filtersDesktop"] input:checked + div {
    background-color: #005bff !important;
  }
  /* RANGE SLIDERS (Цена, Диагональ экрана …) — the same neutraliser erases BOTH
     bars the slider is made of: its grey rail (#b3bcc5) and the light-blue
     selected span (#99bdff). The slider then renders as two blue handles
     floating over nothing, with no track and no indication of the chosen range.
     The selected span is the only div in the rail carrying an inline width+left
     pair (Ozon sets them as live percentages), so it is reachable structurally;
     it must also be lifted a layer, because the two range <input>s follow it in
     DOM order and would paint their track over it. The rail itself has no stable
     hook, so redraw it on the input's own track pseudo, which occupies exactly
     the same box. Paint it as a centred gradient BAND rather than shrinking the
     track to 4px: WebKit lays the thumb out against the track box, so setting a
     height there re-geometries Ozon's round blue handles into squashed bars.
     That pseudo is kept in its OWN rule on purpose: a selector list mixing a
     vendor pseudo with plain selectors is dropped wholesale by the old
     userstyles.org parser. */
  [data-widget="filtersDesktop"] div[style*="width"][style*="left"] {
    background-color: #99bdff !important;
    z-index: 1 !important;
  }
  [data-widget="filtersDesktop"] input[type="range"]::-webkit-slider-runnable-track {
    background-image: linear-gradient(
      to bottom,
      rgba(0, 0, 0, 0) 40%,
      var(--d-border-2) 40%,
      var(--d-border-2) 60%,
      rgba(0, 0, 0, 0) 60%
    ) !important;
  }
  /* Filter labels, category links and the "Посмотреть все" action row
     are token-coloured (--textPrimary / --textSecondary / --textAction);
     no override. The old blanket here greyed every rail link, and a
     `[class*="tsBodyControl500"] { color: blue }` companion then turned
     the whole category rail into a wall of blue links.

     HOVER is the exception: Ozon hardcodes the hovered link colour as a
     literal #0050e0 (16 rules, no token), which is its "pressed blue" —
     fine on the white site, but only ~2.6:1 on our near-black canvas, so
     hovering a link makes it HARDER to read. Lift the hover on the link
     surfaces we own. (A global `a:hover` is deliberately avoided: most
     Ozon anchors — tile titles above all — do not change colour on hover
     natively, and a blanket would invent a blue hover for them.) */
  [data-widget="filtersDesktop"] a:hover,
  [data-widget="filtersDesktop"] label:hover,
  [data-widget="breadCrumbs"] a:hover,
  [data-widget="footer"] a:hover {
    color: var(--d-blue-hover) !important;
  }

  /* ============================================================
     FOOTER
     ============================================================ */
  [data-widget="footer"],
  [data-widget="footer"] > div {
    background-color: var(--d-header) !important;
  }

  /* ============================================================
     CART  (logged-out cart renders the same widget shell)
     ============================================================ */
  [data-widget="cartList"],
  [data-widget="splitColumns"],
  [data-widget="splitItems"],
  [data-widget="cartFooter"],
  [data-widget="cartEmpty"] {
    background-color: transparent !important;
  }

  /* ============================================================
     LINKS / ACCENTS
     Ozon paints action text with --textAction (#005bff), which only
     reaches ~2.9:1 on the near-black base; the token remap lifts it to
     #2e78ff. There is deliberately NO blanket `a { color: blue }` rule:
     most Ozon anchors are NOT action-coloured (catalog flyout links are
     --textSecondary grey, its headings --textPrimary, filter-rail
     categories --textPrimary, tile titles --textPrimary), and painting
     every <a> blue turned the whole category mega-menu and filter rail
     into indistinguishable blue text with headings lost.

     REVIEW LIST is the exception: its links ("Цвет товара: серебристый" on every
     review, one per entry) hardcode the RAW brand blue #005bff instead of going
     through --textAction, so the token lift never reaches them and they sit at
     ~2.9:1 on the base — a whole widget of links below the WCAG floor. The review
     list is lazy-mounted well down the page, so a load-time scan of the PDP never
     sees it. Every <a> in this widget is a genuine action link, so lifting them
     all is safe. (The "Читать полностью" expander next to them is a <span> whose
     only handle is a rotating hash — see the caveat in the review notes; it keeps
     the raw blue.) */
  [data-widget="webListReviews"] a {
    color: var(--d-blue) !important;
  }

  /* VIDEO-DURATION TIMECODE PILL ("00:46") on review (and gallery) video
     thumbnails — Ozon renders it with an INLINE
     `background: var(--clearDarkKey600); color: var(--layerFloor1)`: the
     "…DarkKey" scrim is a translucent near-black (rgba(7,7,7,.48)) laid over
     the video, and --layerFloor1 (a card SURFACE token, natively #fff) is
     reused here as WHITE TEXT on that scrim. Our :root remap of --layerFloor1
     to the dark surface (correct for its background role) turns the timecode
     dark-on-scrim, near-invisible over the video. Rebind the text to white on
     the pill, keyed on BOTH inline tokens so it hits only this scrim+layerFloor1
     pattern — never the elements that use --layerFloor1 as a background-color
     (e.g. the "Ozon Express" badge, whose brand text must stay). The scrim
     itself is left native (translucent black), so white reads exactly as it
     did on the light site. Mounts only with review/gallery video, so a
     load-time scan never sees it. */
  [style*="clearDarkKey600"][style*="var(--layerFloor1)"] {
    color: #ffffff !important;
  }
  /* The PLAY TRIANGLE + ring on those same review-video thumbnails is the second
     --layerFloor1-as-a-glyph use, and it is NOT inline: a class rule does
     `color: var(--layerFlooor1)`-style white on the overlay button. The timecode rule
     above only matched the inline pattern, so the pill next to it went white while the
     play glyph stayed dark-on-video — a half-applied fix that shipped. Both live in the
     same overlay button, which carries a stable aria-label; the button only ever sits on
     top of a photo or video still, so white is right in every instance. */
  button[aria-label="Открыть галерею"] svg {
    color: #ffffff !important;
  }
  /* The REVIEW/GALLERY PHOTO STRIP (data-widget="webListPhotos" — the thumbnail
     rail under the PDP gallery and the "photos from reviews" row above the review
     list) is the THIRD --layerFloor1-as-a-glyph use, and it carries no aria-label,
     so neither the inline-keyed timecode rule nor the aria-label rule above ever
     reached it. Every video thumbnail in those strips therefore drew its play
     ring + triangle in #1c2128 on the video still — the "this is a video"
     affordance, all but gone (14 of them on a review-rich PDP). Every button in
     this widget sits on top of a photo or video still, so white is right in every
     instance, exactly as the site paints it natively. */
  [data-widget="webListPhotos"] button svg {
    color: #ffffff !important;
  }

  /* "Новинка" marketing chip — Ozon ships it as an INLINE pale-green plate with
     green text (`background:#E4FDEC; color:#10C44C`). The inline guard on the
     gallery reset above (correctly) stops flattening inline fills, but this one
     is a LIGHT plate: kept as-is it glares as a white-green tile on the dark PDP.
     Invert it instead of erasing it — the theme's own positive-secondary tint with
     the green lifted to our scale keeps the "new" signal and reads at ~7:1.

     Both hex literals are matched in their rgb() form too, for the same reason the
     horizontal-menu navy is: Ozon's server-rendered markup carries the author's
     hex, but a client-side re-render re-writes the declaration through the CSSOM,
     which serialises every colour as rgb(). A hex-only attribute-substring match
     silently stops matching the moment the component re-renders. */
  [data-widget="webMarketingLabels"] div[style*="#E4FDEC"],
  [data-widget="webMarketingLabels"] div[style*="rgb(228, 253, 236)"] {
    background: var(--bgOpaquePositiveSecondary) !important;
    color: var(--d-green) !important;
  }
  /* "Доберите до скидки" marketing chip — the same LIGHT-inline-plate shape as
     "Новинка" above, but hardcoded as literals (`background:#F2F1FC; color:#5B51DE`)
     instead of going through --bgOpaqueMarketingSecondary, so the token inversion never
     reached it. It sits directly beside the "Скидка от 2 ед" chip, which DOES use the
     token and is correctly dark — the pair shipped half-inverted, one dark pill and one
     pale-lilac tile glaring over the dark gallery. Invert it to match its sibling. */
  [data-widget="webMarketingLabels"] div[style*="#F2F1FC"],
  [data-widget="webMarketingLabels"] div[style*="rgb(242, 241, 252)"] {
    background: var(--bgOpaqueMarketingSecondary) !important;
    color: var(--textMarketing) !important;
  }
  /* "250 баллов за отзыв" points pill — Ozon ships it with an INLINE
     `background: var(--bgOpaqueMarketingSecondary); color: #5B51DE`. We invert the
     plate to dark violet via the token (correct), but the inline label colour is a
     hardcoded dark violet the token remap cannot reach, so on the darkened plate it
     drops to ~2.7:1 (natively ~4.7:1 on the pale plate). Match the pill by its stable
     bg-token name and lift the label to our marketing violet (~4.8:1). The chevron /
     "Б" badge carry their OWN inline colour, so they are untouched. */
  [data-widget="webMarketingLabels"] div[style*="bgOpaqueMarketingSecondary"] {
    color: var(--textMarketing) !important;
  }

  /* SCROLL-TO-TOP DISC (data-widget="homeButton") — a position:fixed
     44px circle that only mounts once you scroll, so no load-time audit
     sees it. Ozon paints it with an INLINE `background: var(--white)`,
     i.e. literal #fff, and its chevron with --graphicNeutral: a stark
     white puck floating over the dark page. --white is a raw palette
     entry (white text on brand fills depends on it), so rebind it only
     inside this widget rather than globally. */
  [data-widget="homeButton"] {
    --white: var(--d-surface) !important;
  }

  /* cookie bubble + any leftover notification surface */
  [data-widget="cookieBubble"] {
    background-color: var(--d-surface) !important;
    color: var(--d-text) !important;
    border-color: var(--d-border) !important;
  }

  /* HEADER / FOOTER / SEARCH-BAR ACTION ICONS — account, orders,
     favourites, cart, camera, magnifier, social glyphs. All are
     `fill: currentColor` off --graphicPrimary / --graphicSecondary /
     --graphicPrimaryInverted, all remapped at :root, so they read on
     the dark header without a per-widget lift. The lift that used to
     sit here also dimmed the magnifier on the brand-blue search CTA
     (natively --graphicPrimaryInverted white) to muted grey. */

  /* ============================================================
     COMPONENTS THAT HARDCODE COLOUR INSTEAD OF USING THE TOKENS.
     Each was found by the dark-on-dark scan AFTER the token remap,
     i.e. these are the genuine leftovers the tokens cannot reach.
     ============================================================ */

  /* PDP aspect labels ("Цвет:", "Оперативная память:") — a literal
     `color: rgba(0,26,51,.6)` on the label span, ~1.2:1 on dark, so the
     label vanished and only its value remained. */
  [data-widget="webAspects"] span span {
    color: var(--d-text-3) !important;
  }

  /* SELECTED variant swatch (colour/model picker) — Ozon rings the
     currently-chosen aspect with a 2px brand-blue border; unselected
     swatches carry a light grey border. Our blanket `* { border-color }`
     softener flattens BOTH to the same dark grey, so the selected variant
     becomes indistinguishable from the others (a lost selection indicator
     no contrast/DOM scan catches — chroma flagged the native blue chroma
     255 -> grey). Ozon renders the current selection as a <div> (not a
     navigable <a> like the unselected ones), so `div[title] > span`
     uniquely reaches each group's selected swatch without any hashed
     class. Restore the blue ring. */
  [data-widget="webAspects"] div[title] > span {
    border-color: var(--d-blue) !important;
  }
  /* The non-swatch aspect chips (processor model, RAM, SSD …) follow the SAME
     selected-vs-unselected convention — the current choice is a <div>, the
     alternatives navigable <a> — but ship NO title, so the swatch rule above
     misses them. The blanket border softener then flattens the selected chip's
     brand-blue ring to grey, erasing which option is chosen (chroma flagged the
     native blue -> grey). pdp_e7 is the chip's border-bearing class; scoping to a
     <div> parent uniquely reaches the selected one without a rotating hash. */
  [data-widget="webAspects"] div > span.pdp_e7 {
    border-color: var(--d-blue) !important;
  }
  /* HOVERING an UNSELECTED aspect chip / swatch natively lifts its ring to the pale
     brand blue #99bdff; our blanket border softener flattens that too, so the whole
     picker gives no feedback at all under the cursor (the ring stays the same dark
     grey it had at rest). No load-time scan can see a state that is not rendered —
     only a native-vs-themed hover diff. The unselected options are the navigable
     <a>s (the current one is a <div>, kept blue by the two rules above), so this
     never competes with the selection ring. Deliberately a dimmer blue than the
     selected ring: on near-black the site's pale #99bdff would outshine the
     selection it is supposed to sit under. */
  [data-widget="webAspects"] a:hover > span {
    border-color: rgba(46, 120, 255, 0.55) !important;
  }

  /* Carousel shelf headings ("Покупают вместе", "Рекомендуем также")
     are LINKS, and the link component pins `color: #070707` on its
     primary variant. Only the 600Medium heading size is targeted: the
     PDP buybox price is 600Large and tile prices are 500Medium, both of
     which must keep their own (white / green / gradient) colour. */
  [class*="tsHeadline600Medium"] {
    color: var(--d-text) !important;
  }

  /* Spec-rating verdicts ("среднее" / "высокая" / "хороший") ship the
     raw brand blue #005bff (~2.9:1 on the base); lift to our blue. */
  [data-widget="contextQuestionsStatistic"] span {
    color: var(--d-blue) !important;
  }

  /* "Есть дешевле" cross-sell label (data-widget="webBestSeller") ships a
     literal `color: rgba(0,26,51,.6)` navy on its descriptor span — ~1.1:1
     on the base, so on dark the label went fully invisible while only its
     "от 294 ₽" price (token-coloured, already light) remained. The navy is a
     hardcoded literal the tokens never reach; lift the widget's text to the
     muted scale so the label reads (the price stays legible muted grey, in
     keeping with this compact secondary cross-sell). */
  [data-widget="webBestSeller"] span {
    color: var(--d-text-3) !important;
  }

  /* Carousel next/prev arrows float over the shelf as a disc painted
     with --ozTextPrimaryNegative ("white text on inverse") used as a
     BACKGROUND, with --ozTextPrimary as the chevron. Once both are
     remapped light the disc is a near-white circle carrying an
     invisible light chevron. `aria-label` is the stable hook (Ozon
     ships it in English). The disabled arrow keeps its faint ground. */
  button[aria-label="Next slide"] > span,
  button[aria-label="Previous slide"] > span {
    background-color: var(--d-surface) !important;
    color: var(--d-text) !important;
  }
  button[disabled][aria-label="Next slide"] > span,
  button[disabled][aria-label="Previous slide"] > span {
    background-color: rgba(255, 255, 255, 0.05) !important;
    color: var(--d-text-4) !important;
  }

  /* generic SVG icons that inherit currentColor stay readable */
  svg {
    color: inherit;
  }

  /* legacy <font color="#000000"> tags (used for some spec-rating
     labels like "Среднее"/"Высокая") set colour via an HTML attribute
     that no class rule can reach — override the element directly */
  font,
  [color] {
    color: var(--d-text-2) !important;
  }
}
